// Des: Atomic JSON blob persistence for config files
// Flo: dirzData once > load file or "{}" > save via unique temp + fsync + rename
// I/O: file name + raw JSON body (UI, serve) > blob in data folder; load never errors, "{}" on failure
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const fres = @import("st-envi-fres.zig");
const CF = .{ .maxz = 8 * 1024 * 1024, .empt = "{}", .envw = "USERPROFILE", .envp = "HOME", .bakz = ".bak", .part = ".bak.part", .conf_file = "aa-conf-main.json", .conf_maxz = 64 * 1024, .data_maxz = 260 };
pub const Tune = struct { port: u16 = 4000, workers: u32 = 4, hist_maxz: u32 = 64, tmoz_seco: u32 = 86400, data: []const u8 = ".zz-base-home-tena/ac-auto-task", envi_fres: bool = true, envi_logi: bool = false };
pub var tune: Tune = .{}; var data_bufz: [CF.data_maxz]u8 = undefined;
const LOCK = .{ .maxz_cnt = 32, .maxz_key = 64, .maxz_val = 32, .defa = "main" }; var lock_keyz: [LOCK.maxz_cnt][LOCK.maxz_key]u8 = undefined; var lock_valz: [LOCK.maxz_cnt][LOCK.maxz_val]u8 = undefined; var lock_kenz: [LOCK.maxz_cnt]u8 = undefined; var lock_venz: [LOCK.maxz_cnt]u8 = undefined; var lock_coun: usize = 0;
pub fn lockOf(iden: []const u8) []const u8 { var bind: usize = LOCK.maxz_cnt; var best: usize = 0; for (0..lock_coun) |indx| { const keyz = lock_keyz[indx][0..lock_kenz[indx]]; if (keyz.len > best and std.mem.startsWith(u8, iden, keyz)) { best = keyz.len; bind = indx; } } return if (bind == LOCK.maxz_cnt) LOCK.defa else lock_valz[bind][0..lock_venz[bind]]; }
fn lockDupe(keyz: []const u8) bool { for (0..lock_coun) |indx| if (std.mem.eql(u8, lock_keyz[indx][0..lock_kenz[indx]], keyz)) return true; return false; }
fn lockApply(valu: std.json.Value) bool { lock_coun = 0; if (valu != .object) return false; var okay = true; var iter = valu.object.iterator(); while (iter.next()) |entr| { const namz = entr.key_ptr.*; if (namz.len == 0 or namz.len > LOCK.maxz_val or entr.value_ptr.* != .array) { okay = false; continue; } for (entr.value_ptr.array.items) |item| { if (item != .string or item.string.len == 0 or item.string.len > LOCK.maxz_key or lock_coun >= LOCK.maxz_cnt or lockDupe(item.string)) { okay = false; continue; } @memcpy(lock_keyz[lock_coun][0..item.string.len], item.string); @memcpy(lock_valz[lock_coun][0..namz.len], namz); lock_kenz[lock_coun] = @intCast(item.string.len); lock_venz[lock_coun] = @intCast(namz.len); lock_coun += 1; } } return okay; }
fn confInt(obj: std.json.ObjectMap, key: []const u8, minz: i64, maxz: i64) ?i64 { const valu = obj.get(key) orelse return null; return switch (valu) { .integer => |numb| if (numb >= minz and numb <= maxz) numb else null, else => null }; }
fn dataOkay(name: []const u8) bool { if (name.len == 0 or name.len > CF.data_maxz or std.mem.eql(u8, name, ".") or std.mem.eql(u8, name, "..")) return false; var segs = std.mem.tokenizeAny(u8, name, "/\\"); while (segs.next()) |seg| { if (std.mem.eql(u8, seg, "..")) return false; } for (name) |byte| { if (!std.ascii.isAlphanumeric(byte) and byte != '.' and byte != '_' and byte != '-' and byte != '/' and byte != '\\' and byte != ':' and byte != '~') return false; } return true; }
const DATA_KEYZ = if (builtin.os.tag == .windows) "apps_data_loca_wind" else "apps_data_loca_unix";
pub fn confApply(allo: std.mem.Allocator, data: []const u8) ?[]const u8 { tune = .{}; lock_coun = 0; const root = std.json.parseFromSliceLeaky(std.json.Value, allo, data, .{}) catch return "aa-conf-main.json is not valid JSON, defaults used"; const obj = switch (root) { .object => |objz| objz, else => return "aa-conf-main.json must be an object, defaults used" }; var badz = false; if (obj.get("port") != null) { if (confInt(obj, "port", 1, 65535)) |numb| tune.port = @intCast(numb) else badz = true; } if (obj.get("jobs_same_time") != null) { if (confInt(obj, "jobs_same_time", 1, 8)) |numb| tune.workers = @intCast(numb) else badz = true; } if (obj.get("cmds_hist_maxz") != null) { if (confInt(obj, "cmds_hist_maxz", 1, 10_000)) |numb| tune.hist_maxz = @intCast(numb) else badz = true; } if (obj.get("time_limi_seco") != null) { if (confInt(obj, "time_limi_seco", 1, 24 * 60 * 60)) |numb| tune.tmoz_seco = @intCast(numb) else badz = true; } if (obj.get("envi_mode")) |valu| { if (valu == .string and std.mem.eql(u8, valu.string, "fresh")) {} else if (valu == .string and std.mem.eql(u8, valu.string, "login")) tune.envi_logi = true else if (valu == .string and std.mem.eql(u8, valu.string, "inherit")) tune.envi_fres = false else badz = true; } if (obj.get("lock_list")) |valu| { if (!lockApply(valu)) badz = true; } if (obj.get(DATA_KEYZ)) |valu| { if (valu == .string and dataOkay(valu.string)) { @memcpy(data_bufz[0..valu.string.len], valu.string); tune.data = data_bufz[0..valu.string.len]; } else badz = true; } return if (badz) "aa-conf-main.json: a bad value was ignored, its default used" else null; }
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, root: []const u8) ?[]const u8 { const path = std.fs.path.join(allo, &.{ root, CF.conf_file }) catch return null; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.conf_maxz)) catch return null; return confApply(allo, data); }
pub const MAXZ_BLOB = CF.maxz; pub const HOME_VARZ = if (builtin.os.tag == .windows) CF.envw else CF.envp; const BAKZ_FILE = [_][]const u8{ "config.json", "output.json" };
pub fn enviLive() std.process.Environ { if (builtin.os.tag == .windows) return .{ .block = .global }; return .{ .block = .{ .slice = std.mem.span(std.c.environ) } }; }
// copy of the env for a child: fresh = registry changes made after launch are merged in (Windows); inherit = the launch env as is
pub fn enviMap(allo: std.mem.Allocator) !std.process.Environ.Map { var mapz = try enviLive().createMap(allo); if (tune.envi_fres) fres.applyFres(allo, &mapz); return mapz; }
pub fn enviDiff(allo: std.mem.Allocator) ![][]const u8 { var base = try enviLive().createMap(allo); var fresh = try base.clone(allo); fres.applyFres(allo, &fresh); return fres.diffNames(allo, &base, &fresh); }
var dirz_bufz: [1024]u8 = undefined; var dirz_lenz: std.atomic.Value(usize) = .init(0);
// data folder: absolute path as is, "~/x" or "x" under the user folder
pub fn dataBase(allo: std.mem.Allocator) ![]const u8 { if (std.fs.path.isAbsolute(tune.data)) return tune.data; const home = std.process.Environ.getAlloc(enviLive(), allo, HOME_VARZ) catch return error.NoHomeDir; const rest = if (std.mem.startsWith(u8, tune.data, "~/") or std.mem.startsWith(u8, tune.data, "~\\")) tune.data[2..] else tune.data; return std.fs.path.join(allo, &.{ home, rest }); }
pub fn dirzData(allo: std.mem.Allocator, iozz: std.Io) ![]const u8 { const lenz = dirz_lenz.load(.acquire); if (lenz > 0) return dirz_bufz[0..lenz]; const dirz = try dataBase(allo); if (dirz.len > dirz_bufz.len) return dirz; std.Io.Dir.cwd().createDirPath(iozz, dirz) catch {}; @memcpy(dirz_bufz[0..dirz.len], dirz); dirz_lenz.store(dirz.len, .release); return dirz_bufz[0..dirz.len]; }
pub fn load(allo: std.mem.Allocator, iozz: std.Io, name: []const u8) []const u8 { const dirz = dirzData(allo, iozz) catch return CF.empt; const path = std.fs.path.join(allo, &.{ dirz, name }) catch return CF.empt; const data = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(MAXZ_BLOB)) catch return CF.empt; if (data.len == 0) return CF.empt; return data; }
pub var mute_save: std.Io.Mutex = .init; var temp_sequ: std.atomic.Value(u32) = .init(0);
pub fn save(allo: std.mem.Allocator, iozz: std.Io, name: []const u8, body: []const u8) !void { try mute_save.lock(iozz); defer mute_save.unlock(iozz); return lockSave(allo, iozz, name, body); }
pub fn lockSave(allo: std.mem.Allocator, iozz: std.Io, name: []const u8, body: []const u8) !void { const dirz = try dirzData(allo, iozz); const path = try std.fs.path.join(allo, &.{ dirz, name }); if (std.fs.path.dirname(path)) |pare| std.Io.Dir.cwd().createDirPath(iozz, pare) catch {}; const sequ = temp_sequ.fetchAdd(1, .monotonic); const temp = try std.fmt.allocPrint(allo, "{s}.{d}.tmp", .{ path, sequ }); var file = try std.Io.Dir.cwd().createFile(iozz, temp, .{ .truncate = true, .read = true }); { errdefer file.close(iozz); try file.writePositionalAll(iozz, body, 0); file.sync(iozz) catch {}; } file.close(iozz); for (BAKZ_FILE) |item| if (std.mem.eql(u8, item, name)) { bakzKeep(allo, iozz, path); break; }; try std.Io.Dir.rename(.cwd(), temp, .cwd(), path, iozz); }
fn bakzKeep(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) void { const part = std.fmt.allocPrint(allo, "{s}" ++ CF.part, .{path}) catch return; const bakz = std.fmt.allocPrint(allo, "{s}" ++ CF.bakz, .{path}) catch return; const cwdz = std.Io.Dir.cwd(); cwdz.copyFile(path, cwdz, part, iozz, .{}) catch return; std.Io.Dir.rename(.cwd(), part, .cwd(), bakz, iozz) catch {}; }
